@Transactional
public void updateUserProfile(String userId, UserProfileDto dto) {
    try {
        userRepository.updateUser(userId, dto);
        cacheManager.getCache("users").evict(userId);
        eventPublisher.publishEvent(new CacheInvalidationEvent(userId));
    } catch (DataAccessException | TransientDataAccessException ex) {
        log.error("Database mutation failed for user: {}, rolling back cache eviction", userId);
        throw new ServiceExecutionException("Failed to update profile, aborting cache sync", ex);
    } catch (Exception ex) {
        log.warn("Non-fatal NIO or cache communication error during invalidation for user: {}", userId);
        resilientInvalidationQueue.offer(new InvalidationTask(userId));
    }
}
